import{_ as i,o as s,c as e,a2 as t}from"./chunks/framework.Ddyno5UB.js";const g=JSON.parse('{"title":"Git Fundamentals","description":"","frontmatter":{},"headers":[],"relativePath":"git/1-fundamentals.md","filePath":"git/1-fundamentals.md"}'),n={name:"git/1-fundamentals.md"};function l(o,a,r,h,p,d){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="git-fundamentals" tabindex="-1">Git Fundamentals <a class="header-anchor" href="#git-fundamentals" aria-label="Permalink to &quot;Git Fundamentals&quot;">​</a></h1><p>Git is a distributed version control system designed to handle everything from small to massive projects with speed and efficiency. Unlike older systems (like SVN) that store files as a list of changes, Git thinks of its data more like a series of snapshots of a miniature filesystem.</p><h2 id="the-three-trees" tabindex="-1">The Three Trees <a class="header-anchor" href="#the-three-trees" aria-label="Permalink to &quot;The Three Trees&quot;">​</a></h2><p>To master Git, you must understand its core philosophy: <strong>The Three Trees</strong>.</p><ol><li><strong>Working Directory:</strong> The actual files you see and edit on your computer&#39;s hard drive.</li><li><strong>Staging Area (Index):</strong> A conceptual &quot;loading dock&quot; where you place modified files you are preparing to commit.</li><li><strong>Local Repository (HEAD):</strong> The actual database where Git permanently stores your committed snapshots.</li></ol><p>The standard Git workflow moves files from the Working Directory -&gt; Staging Area -&gt; Local Repository.</p><h2 id="basic-operations" tabindex="-1">Basic Operations <a class="header-anchor" href="#basic-operations" aria-label="Permalink to &quot;Basic Operations&quot;">​</a></h2><h3 id="_1-initialization" tabindex="-1">1. Initialization <a class="header-anchor" href="#_1-initialization" aria-label="Permalink to &quot;1. Initialization&quot;">​</a></h3><p>Turn any normal directory into a Git repository.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Initialize an empty repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Alternatively, download an existing repository from the internet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/torvalds/linux.git</span></span></code></pre></div><h3 id="_2-checking-status" tabindex="-1">2. Checking Status <a class="header-anchor" href="#_2-checking-status" aria-label="Permalink to &quot;2. Checking Status&quot;">​</a></h3><p>Always run this command before doing anything. It tells you exactly what tree your files are currently in.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><h3 id="_3-adding-to-the-staging-area" tabindex="-1">3. Adding to the Staging Area <a class="header-anchor" href="#_3-adding-to-the-staging-area" aria-label="Permalink to &quot;3. Adding to the Staging Area&quot;">​</a></h3><p>You&#39;ve made changes to a file. Now you need to move it to the Staging Area (the loading dock).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stage a specific file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stage all modified and new files in the current directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h3 id="_4-committing" tabindex="-1">4. Committing <a class="header-anchor" href="#_4-committing" aria-label="Permalink to &quot;4. Committing&quot;">​</a></h3><p>Take a snapshot of everything currently sitting in the Staging Area and save it permanently to the Local Repository.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Add user authentication feature&quot;</span></span></code></pre></div><h3 id="_5-viewing-history" tabindex="-1">5. Viewing History <a class="header-anchor" href="#_5-viewing-history" aria-label="Permalink to &quot;5. Viewing History&quot;">​</a></h3><p>Look back at the snapshots you (and others) have taken.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View the full commit history</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View a condensed, one-line-per-commit history</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span></code></pre></div><h2 id="ignoring-files" tabindex="-1">Ignoring Files <a class="header-anchor" href="#ignoring-files" aria-label="Permalink to &quot;Ignoring Files&quot;">​</a></h2><p>You do not want to track every file in your project. Compiled binaries, temporary files, IDE configs (like <code>.vscode</code>), and secrets (like <code>.env</code> files) should never be committed.</p><p>You tell Git what to ignore by creating a file named <code>.gitignore</code> in the root of your repository.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Example .gitignore</span></span>
<span class="line"><span>node_modules/</span></span>
<span class="line"><span>*.log</span></span>
<span class="line"><span>.env</span></span>
<span class="line"><span>build/</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If a file is already tracked by Git (already committed), adding it to <code>.gitignore</code> will <strong>not</strong> stop Git from tracking it. You must first untrack it using <code>git rm --cached &lt;file&gt;</code>.</p></div>`,27)])])}const k=i(n,[["render",l]]);export{g as __pageData,k as default};
